import './App.css';
import { useEffect, useState } from 'react';
import Video_list from './components/video_list/video_list';
import Search from './components/search_header/search_header';
import Search_header from './components/search_header/search_header';

function App() {
  const [videos, setVideos] = useState([]);

  useEffect(() => {
    const requestOptions = {
      method: 'GET',
      redirect: 'follow'
    };

    fetch("https://youtube.googleapis.com/youtube/v3/search?part=snippet&maxResults=25&q=bts&key=AIzaSyALd5gN0lZ5gFbk7dys3373SqkmhNcF_dE&key=AIzaSyALd5gN0lZ5gFbk7dys3373SqkmhNcF_dE", requestOptions)
      .then(response => response.json())
      .then(result => setVideos(result.items))
      .catch(error => console.log('error', error));
  }, [])

  return <>
    <Search_header></Search_header>
    <Video_list videos={videos}></Video_list>
  </>
}

export default App;
